import decodeStandalone from '../lzma-decoder.mjs';import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';import {test} from 'node:test';
const root=new URL('./',import.meta.url),ctx=vm.createContext({Blob,DecompressionStream,TextDecoder,Uint8Array,Uint16Array,Uint32Array,DataView});vm.runInContext(fs.readFileSync(new URL('../source/archive.js',root),'utf8'),ctx);
const old=vm.createContext({Blob,DecompressionStream,TextDecoder,Uint8Array,Uint16Array,Uint32Array,DataView});vm.runInContext(fs.readFileSync(new URL('references/lzma1-sdk.js',root),'utf8'),old);
ctx.NES={};vm.runInContext(fs.readFileSync(new URL('../source/rom.js',root),'utf8'),ctx);
const cases=JSON.parse(fs.readFileSync(new URL('raw-cases.json',root)));
for(const item of cases)test('raw/reference '+item.name,()=>{const packed=fs.readFileSync(new URL('raw/'+item.packed,root)),props=Buffer.from(item.properties,'hex'),expected=fs.readFileSync(new URL('raw/'+item.data,root));const actual=ctx.decodeLzma(packed,props,item.size);assert.deepEqual(Buffer.from(decodeStandalone(packed,props,item.size)),expected);assert.deepEqual(Buffer.from(actual),expected);const ref=old.unpackFolder(packed,{start:0,packed:packed.length,properties:props,size:item.size,method:'3.1.1'});assert.deepEqual(Buffer.from(actual),Buffer.from(ref));});
test('truncation, properties, bounds and dictionary normalization',()=>{const c=cases.find(x=>x.name.startsWith('distance-3-0-2-4096'));const packed=fs.readFileSync(new URL('raw/'+c.packed,root)),props=Buffer.from(c.properties,'hex');assert.throws(()=>ctx.decodeLzma(packed.subarray(0,packed.length/2),props,c.size));assert.throws(()=>ctx.decodeLzma(packed,Buffer.from([255,0,0,0,0]),c.size));assert.throws(()=>ctx.decodeLzma(packed,props,17*1024*1024));const zero=Buffer.from(props);zero.fill(0,1);assert.deepEqual(Buffer.from(ctx.decodeLzma(packed,zero,c.size)),fs.readFileSync(new URL('raw/'+c.data,root)));});
async function read(name){const data=fs.readFileSync(new URL('archives/'+name,root));return ctx.readGameFile({name,arrayBuffer:async()=>data.buffer.slice(data.byteOffset,data.byteOffset+data.length)});}
for(const name of ['lzma.7z','lzma-header.7z','lzma2.7z','lzma2-header.7z'])test('container '+name,async()=>assert.deepEqual(Buffer.from(await read(name)),fs.readFileSync(new URL('expected.nes',root))));
for(const name of ['deflate.zip','comment.zip','multiple.zip','stored.zip'])test('reject '+name,async()=>assert.rejects(async()=>ctx.NES.parse(new Uint8Array(await read(name)))));
